d.deleted_at IS NULL AND p.deleted_at IS NULL
    AND (p.owner_user_id=#{actor}
      OR EXISTS(SELECT 1 FROM sop_project_member m WHERE m.project_id=p.id AND m.user_id=#{actor} AND m.member_status=1))

    AND d.managing_project_id=#{projectId}
    AND (LOCATE(#{keyword},d.code)>0 OR LOCATE(#{keyword},d.name)>0)
